<?php
require __DIR__.'/company_identity_transaction.php';
require_once APPPATH.'services/issuers/IssuerRegistry.php';
$registry=new IssuerRegistry($db,$p);
essentialCheck(!$registry->canCreate(13),'ordinary administrator cannot create companies implicitly');
essentialCheck($registry->catalog(13)===[],'ordinary administrator cannot list foreign identities');
essentialCheck(array_column($registry->catalog(12),'id')===[41],'catalog constrained to active memberships');
settingThrows(fn()=>$registry->saveIssuer(13,['legal_name'=>'Denied','tax_id'=>'11222333000181']),'issuer_access_denied','global administrator cannot create across tenant boundary');
$new=$registry->saveIssuer(7,['legal_name'=>'Wizard company','tax_id'=>'11222333000181','profile'=>['invoice_company_city'=>'Wizard city']]);
essentialCheck($identity->get($new,'invoice_company_city')==='Wizard city','registration saves canonical profile');
essentialCheck($store->get($new,'smtp_password')==='','new company still inherits no SMTP secret');
settingThrows(fn()=>$registry->saveIssuer(12,['legal_name'=>'Foreign edit','tax_id'=>'11222333000181'],$new),'issuer_access_denied','member cannot edit another company via guessed ID');
$identity->save(41,12,['profile'=>['invoice_company_city'=>'Settings city']]);
$registry->saveIssuer(12,['legal_name'=>'Registered identity','tax_id'=>'12345678000195','profile'=>['invoice_company_city'=>'Registry city']],41);
essentialCheck($identity->get(41,'companyname')==='Registered identity' && $identity->get(41,'invoice_company_city')==='Registry city','resource-authorized staff edits same canonical source');
$before=$identity->read(41);
$db->failOn='INSERT INTO '.$p.'issuers_audit';
settingThrows(fn()=>$registry->saveIssuer(12,['legal_name'=>'Must rollback','tax_id'=>'12345678000195','profile'=>['invoice_company_city'=>'Must rollback']],41),'issuer_storage_failed','audit failure rolls back whole registration');
$db->failOn=null;
essentialCheck($identity->read(41)===$before,'registry identity and profile roll back together');
// Existing-company modal writer: stale revisions cannot overwrite another session.
$revision=$registry->identityRevision(12,41);
$countBefore=(int)$db->query("SELECT COUNT(*) n FROM {$p}issuers_registry")->row()->n;
$secretBefore=$store->get(41,'smtp_password');
$registry->updateExistingIdentity(12,['legal_name'=>'Edited existing','tax_id'=>'12345678000195','active'=>'0','profile'=>['invoice_company_city'=>'Edited city']],41,$revision);
essentialCheck($identity->get(41,'companyname')==='Edited existing','existing editor writes canonical identity');
essentialCheck((int)$db->query("SELECT active FROM {$p}issuers_registry WHERE id=41")->row()->active===1,'identity editor cannot deactivate issuer');
essentialCheck((int)$db->query("SELECT COUNT(*) n FROM {$p}issuers_registry")->row()->n===$countBefore,'identity editor never creates another company');
essentialCheck($store->get(41,'smtp_password')===$secretBefore,'identity editor preserves credentials');
$edited=$identity->read(41);
settingThrows(fn()=>$registry->updateExistingIdentity(12,['legal_name'=>'Stale','tax_id'=>'12345678000195'],41,$revision),'company_identity_revision_stale','stale editor cannot overwrite committed identity');
essentialCheck($identity->read(41)===$edited,'stale attempt leaves entire canonical identity untouched');
settingThrows(fn()=>$registry->identityRevision(13,41),'issuer_access_denied','revision cannot expose foreign identity');
settingThrows(fn()=>$registry->updateExistingIdentity(13,['legal_name'=>'Denied','tax_id'=>'12345678000195'],41,$revision),'issuer_access_denied','editor preserves service ACL');
settingThrows(fn()=>$registry->updateExistingIdentity(12,['legal_name'=>'Invalid','tax_id'=>'12345678000195'],41,''),'company_identity_revision_invalid','missing revision rejected');
$currentRevision=$registry->identityRevision(12,41);
$db->failOn='INSERT INTO '.$p.'issuers_audit';
settingThrows(fn()=>$registry->updateExistingIdentity(12,['legal_name'=>'Rollback edit','tax_id'=>'12345678000195'],41,$currentRevision),'issuer_storage_failed','editor audit failure rolls back transaction');
$db->failOn=null;
essentialCheck($identity->read(41)===$edited&&$registry->identityRevision(12,41)===$currentRevision,'failed editor preserves identity and revision');
echo 'Company registration identity: '.$GLOBALS['essentialChecks']." total checks passed.\n";
